use super::kit::*;
pub fn commands()->Vec<Command>{vec![Command{name:"sample_advection_field",description:"Sample a raw 3D advection field for particle flow: curl3, potential3 or worley3. Raw 3D advection field sampler for particle flow: curl3 (divergence-free from three planar C2 FBM potentials), potential3 (compressible gradient), worley3 (compressible F2-F1 ridge flow). Analytic gradients, deterministic per seed. Not a fluid solver; no temporal coherence claim.",mutates:false,schema:obj(vec![("field",json!({"type":"object"})),("points",json!({"type":"array"}))],&["field","points"]),run:|_,a|{let field:crate::particle_advect::Advect=serde_json::from_value(a.get("field").ok_or("field required")?.clone()).map_err(|e|e.to_string())?;let points=serde_json::from_value::<Vec<[f64;3]>>(a.get("points").ok_or("points required")?.clone()).map_err(|e|e.to_string())?;if points.is_empty()||points.len()>65536{return Err("points 1..65536".into());}let mut vectors=Vec::with_capacity(points.len());for p in &points{vectors.push(field.velocity(*p)?);}Ok(json!({"vectors":vectors,"solenoidal":field.solenoidal(),"velocity_bound":field.bound()}))}}]}
